mapper.select:
SELECT activity.id, activity.title, activity.status, activity.position, activity.cover_img, activity.activity_belong_to_school_id, school_info.name AS activity_belong_to_school_name, activity_schedule.activity_start_time, activity_schedule.activity_end_time FROM activity INNER JOIN activity_schedule ON activity_schedule.activity_id = activity.id AND activity_schedule.deleted_flag = 0 LEFT JOIN school_info ON activity.activity_belong_to_school_id = school_info.id WHERE activity.deleted_flag = 0 AND activity.status IN (0, 1, 2, 3, 4) AND activity_schedule.activity_start_time < #{endTimeExclusive} AND activity_schedule.activity_end_time >= #{startTime}
AND activity.activity_belong_to_school_id = #{schoolId}
ORDER BY activity_schedule.activity_start_time ASC, activity.id ASC
